<?php
namespace App\Livewire\Restaurant;
use App\Models\Restaurant\Order;use App\Models\Restaurant\OrderItem;use App\Models\Restaurant\Reservation;use App\Models\Invoicing\StockMovement;use Livewire\Attributes\Layout;use Livewire\Attributes\Title;use Livewire\Component;
#[Layout('layouts.app')] #[Title('Relatórios - Restaurante')]
class Reports extends Component {public string $from='',$to='';public function mount(){ $this->from=now()->startOfMonth()->format('Y-m-d');$this->to=now()->format('Y-m-d');}public function render(){ $tid=activeTenantId();$orders=Order::withoutGlobalScopes()->where('tenant_id',$tid)->whereBetween('created_at',[$this->from.' 00:00:00',$this->to.' 23:59:59']);$closed=(clone $orders)->whereIn('status',['billed','partially_billed'])->get();$top=OrderItem::withoutGlobalScopes()->where('tenant_id',$tid)->whereHas('order',fn($q)=>$q->whereBetween('created_at',[$this->from.' 00:00:00',$this->to.' 23:59:59']))->selectRaw('product_name, SUM(quantity) qty, SUM(line_total) total')->groupBy('product_name')->orderByDesc('qty')->limit(10)->get();$stats=['sales'=>$closed->sum('grand_total'),'orders'=>$closed->count(),'ticket'=>$closed->count()?$closed->avg('grand_total'):0,'reservations'=>Reservation::withoutGlobalScopes()->where('tenant_id',$tid)->whereBetween('reserved_at',[$this->from.' 00:00:00',$this->to.' 23:59:59'])->count(),'waste'=>StockMovement::withoutGlobalScopes()->where('tenant_id',$tid)->where('reference_type','restaurant_waste')->whereBetween('created_at',[$this->from.' 00:00:00',$this->to.' 23:59:59'])->sum('total_cost')];return view('livewire.restaurant.reports',compact('stats','top'));}}
